import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { useSelector } from "react-redux";
import api from "../../api/axios";

const TicketDetail = () => {
  const { id } = useParams();
  const { user } = useSelector((state) => state.auth);
  const isAdmin = user?.is_staff || false;

  const [ticket, setTicket] = useState(null);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isEditing, setIsEditing] = useState(false);

  const [editForm, setEditForm] = useState({
    status: "",
    assigned_to: "",
    confidential_notes: "",
  });

  useEffect(() => {
    const fetchTicket = async () => {
      try {
        setLoading(true);
        const res = await api.get(`tickets/${id}/`);
        setTicket(res.data);
        setEditForm({
          status: res.data.status || "OPEN",
          assigned_to: res.data.assigned_to || "",
          confidential_notes: res.data.confidential_notes || "",
        });
      } catch (err) {
        console.error(err);
        setError("Failed to load ticket details.");
      } finally {
        setLoading(false);
      }
    };
    fetchTicket();
  }, [id]);

  useEffect(() => {
    if (isAdmin) {
      const fetchUsers = async () => {
        try {
          const res = await api.get("/auth/users/");
          setUsers(res.data);
        } catch (err) {
          console.warn("Could not load users:", err);
        }
      };
      fetchUsers();
    }
  }, [isAdmin]);

  const handleSave = async () => {
    try {
      const updateData = {};
      if (editForm.status !== ticket.status) updateData.status = editForm.status;
      if (editForm.assigned_to !== ticket.assigned_to)
        updateData.assigned_to = editForm.assigned_to || null;
      if (editForm.confidential_notes !== ticket.confidential_notes)
        updateData.confidential_notes = editForm.confidential_notes;

      if (Object.keys(updateData).length === 0) {
        setIsEditing(false);
        return;
      }

      // Fixed: Explicit Content-Type header
      const res = await api.patch(`tickets/${id}/`, updateData, {
        headers: { "Content-Type": "application/json" },
      });

      setTicket(res.data);
      setIsEditing(false);
      alert("Ticket updated successfully!");
    } catch (err) {
      console.error("Update failed:", err.response?.data || err);
      alert("Failed to update ticket.");
    }
  };

  const updateStatus = async (newStatus) => {
    try {
      // Fixed: Explicit header here too
      const res = await api.patch(
        `tickets/${id}/`,
        { status: newStatus },
        { headers: { "Content-Type": "application/json" } }
      );
      setTicket(res.data);
    } catch (err) {
      console.error("Status update failed:", err);
    }
  };

  if (loading) return <div style={styles.loading}>Loading ticket details...</div>;
  if (error) return <div style={styles.error}>{error}</div>;
  if (!ticket) return null;

  const getPriorityBadge = (priority) => {
    const p = priority?.toUpperCase() || "";
    if (p === "HIGH") return { bg: "#ff4d4f", text: "High" };
    if (p === "MEDIUM") return { bg: "#faad14", text: "Medium" };
    if (p === "LOW") return { bg: "#52c41a", text: "Low" };
    return { bg: "#d9d9d9", text: priority || "N/A" };
  };

  const getStatusBadge = (status) => {
    const s = status?.toUpperCase() || "";
    switch (s) {
      case "OPEN": return { bg: "#1890ff", text: "Open" };
      case "IN_PROGRESS": return { bg: "#faad14", text: "In Progress" };
      case "RESOLVED": return { bg: "#52c41a", text: "Resolved" };
      case "PARTIALLY_CLOSED": return { bg: "#9254de", text: "Partially Closed" };
      default: return { bg: "#d9d9d9", text: status || "N/A" };
    }
  };

  const priorityBadge = getPriorityBadge(ticket.priority);
  const statusBadge = getStatusBadge(ticket.status);

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        {/* Header */}
        <div style={styles.header}>
          <h3 style={styles.title}>Ticket #{id} - {ticket.title}</h3>
          <div style={styles.badges}>
            <span style={{ ...styles.badge, background: priorityBadge.bg }}>
              {priorityBadge.text}
            </span>
            <span style={{ ...styles.badge, background: statusBadge.bg }}>
              {statusBadge.text}
            </span>
          </div>
        </div>

        {/* Description */}
        <p style={styles.description}>{ticket.description}</p>

        {/* Attachments */}
        {ticket.attachments?.length > 0 ? (
          <div style={styles.section}>
            <strong style={styles.sectionTitle}>Attachments:</strong>
            <ul style={styles.attachmentList}>
              {ticket.attachments.map((att, idx) => (
                <li key={idx}>
                  <a href={att.file} target="_blank" rel="noopener noreferrer" style={styles.link}>
                    {att.file.split("/").pop() || `Attachment ${idx + 1}`}
                  </a>
                </li>
              ))}
            </ul>
          </div>
        ) : (
          <p style={styles.noData}>No attachments</p>
        )}

        {/* Admin Controls - Compact Grid Layout */}
        {isAdmin && (
          <>
            <hr style={styles.hr} />
            <div style={styles.section}>
              <div style={styles.adminHeader}>
                <h5 style={styles.sectionTitle}>Admin Controls</h5>
                <div>
                  {!isEditing ? (
                    <button onClick={() => setIsEditing(true)} style={styles.editButton}>
                      Edit
                    </button>
                  ) : (
                    <>
                      <button onClick={handleSave} style={styles.saveButton}>Save</button>
                      <button onClick={() => setIsEditing(false)} style={styles.cancelButton}>Cancel</button>
                    </>
                  )}
                </div>
              </div>

              <div style={styles.formGrid}>
                {/* Status */}
                <div style={styles.formRow}>
                  <strong>Status:</strong>
                  {isEditing ? (
                    <select
                      value={editForm.status}
                      onChange={(e) => setEditForm({ ...editForm, status: e.target.value })}
                      style={styles.select}
                    >
                      <option value="OPEN">Open</option>
                      <option value="IN_PROGRESS">In Progress</option>
                      <option value="RESOLVED">Resolved</option>
                      <option value="PARTIALLY_CLOSED">Partially Closed</option>
                    </select>
                  ) : (
                    <span style={styles.value}>{statusBadge.text}</span>
                  )}
                </div>

                {/* Assigned To */}
                <div style={styles.formRow}>
                  <strong>Assigned To:</strong>
                  {isEditing ? (
                    <select
                      value={editForm.assigned_to}
                      onChange={(e) => setEditForm({ ...editForm, assigned_to: e.target.value })}
                      style={styles.select}
                    >
                      <option value="">Unassigned</option>
                      {users.map((u) => (
                        <option key={u.id} value={u.id}>
                          {u.email} (ID: {u.id})
                        </option>
                      ))}
                    </select>
                  ) : (
                    <span style={styles.value}>
                      {ticket.assigned_to ? `User #${ticket.assigned_to}` : "Unassigned"}
                    </span>
                  )}
                </div>

                {/* Confidential Notes */}
                <div style={styles.formRowFull}>
                  <strong>Confidential Notes:</strong>
                  {isEditing ? (
                    <textarea
                      value={editForm.confidential_notes}
                      onChange={(e) => setEditForm({ ...editForm, confidential_notes: e.target.value })}
                      rows="3"
                      style={styles.textarea}
                      placeholder="Encrypted & visible only to admins"
                    />
                  ) : (
                    <p style={styles.notes}>
                      {ticket.confidential_notes || <em>No notes</em>}
                    </p>
                  )}
                </div>
              </div>

              {/* Quick Resolve Button */}
              {!isEditing && ticket.status !== "RESOLVED" && (
                <button onClick={() => updateStatus("RESOLVED")} style={styles.resolveButton}>
                  Mark as Resolved
                </button>
              )}
            </div>
          </>
        )}

        {/* Audit Log */}
        <hr style={styles.hr} />
        <div style={styles.section}>
          <h5 style={styles.sectionTitle}>Audit Log</h5>
          {ticket.audit_logs?.length > 0 ? (
            <ul style={styles.auditList}>
              {ticket.audit_logs.map((log) => (
                <li key={log.id} style={styles.auditItem}>
                  <span style={styles.auditTime}>
                    {new Date(log.created_at || log.timestamp).toLocaleString()}
                  </span>
                  <span>{log.message}</span>
                </li>
              ))}
            </ul>
          ) : (
            <p style={styles.noData}>No audit logs available</p>
          )}
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: { padding: "40px 20px", maxWidth: "900px", margin: "0 auto", background: "#f9faff", minHeight: "100vh", fontFamily: "Arial, sans-serif" },
  card: { background: "#fff", borderRadius: "16px", boxShadow: "0 8px 32px rgba(0,0,0,0.1)", padding: "32px" },
  header: { display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", marginBottom: "24px", gap: "12px" },
  title: { fontSize: "28px", fontWeight: "700", color: "#4527a0", margin: 0 },
  badges: { display: "flex", gap: "12px" },
  badge: { padding: "8px 16px", borderRadius: "24px", color: "#fff", fontSize: "14px", fontWeight: "600", textTransform: "uppercase" },
  description: { fontSize: "16px", color: "#333", marginBottom: "24px", lineHeight: "1.6" },
  section: { marginBottom: "32px" },
  sectionTitle: { fontSize: "20px", color: "#4527a0", marginBottom: "12px" },
  attachmentList: { paddingLeft: "20px", margin: "8px 0" },
  link: { color: "#667eea", textDecoration: "none" },
  noData: { color: "#888", fontStyle: "italic" },
  hr: { border: "none", borderTop: "1px solid #eee", margin: "32px 0" },

  // Admin Section - Clean Grid
  adminHeader: { display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" },
  formGrid: { display: "grid", gap: "16px" },
  formRow: { display: "flex", alignItems: "center", gap: "12px", flexWrap: "wrap" },
  formRowFull: { display: "flex", flexDirection: "column", gap: "8px" },
  value: { fontWeight: "600", color: "#333" },
  select: { padding: "10px", borderRadius: "8px", border: "1px solid #ddd", fontSize: "15px", minWidth: "200px" },
  textarea: { width: "100%", padding: "12px", borderRadius: "8px", border: "1px solid #ddd", fontSize: "15px", resize: "vertical" },
  notes: { background: "#f8f9fa", padding: "12px", borderRadius: "8px", border: "1px solid #e0e0e0", marginTop: "8px", minHeight: "60px" },

  // Buttons
  editButton: { padding: "8px 16px", background: "#667eea", color: "#fff", border: "none", borderRadius: "8px", cursor: "pointer", fontWeight: "600" },
  saveButton: { padding: "10px 20px", background: "#52c41a", color: "#fff", border: "none", borderRadius: "8px", cursor: "pointer", fontWeight: "600", marginRight: "8px" },
  cancelButton: { padding: "10px 20px", background: "#ccc", color: "#333", border: "none", borderRadius: "8px", cursor: "pointer" },
  resolveButton: { padding: "12px 24px", background: "linear-gradient(135deg, #52c41a, #389e0d)", color: "#fff", border: "none", borderRadius: "8px", fontSize: "16px", fontWeight: "600", cursor: "pointer", marginTop: "16px" },

  // Audit
  auditList: { listStyle: "none", padding: 0 },
  auditItem: { padding: "12px", background: "#f8f9fa", borderRadius: "8px", marginBottom: "10px", display: "flex", flexDirection: "column", gap: "4px" },
  auditTime: { fontWeight: "bold", color: "#666", fontSize: "14px" },

  loading: { textAlign: "center", fontSize: "24px", color: "#4527a0", padding: "100px 0" },
  error: { textAlign: "center", fontSize: "20px", color: "#ff4d4f", padding: "100px 0" },
};

export default TicketDetail;
